/* OTOMATİK ÜRETİLDİ - düzenlemeyin. Kaynak: site-src/ (araclar/build-site-bundle.js) */
window.LP_SITE = {"css":"/* Love Panel 3.0 - Site stili\n * Renkler iki ana değişkenden (--p ana, --s ikincil) türetilir; değerleri site.js yazar.\n * Bölümler: 1 Temel · 2 Açılış · 3 Hero · 4 Albüm ortak · 5-9 Anı tasarımları · 10 Oynatıcı · 11 Mobil\n */\n\n/* ===== 1. Temel ===== */\n:root{\n  --p:#a77af2;--s:#ff9fcf;--bg:#0f0b1f;--bg2:#1d1238;--tx:#f6f1ff;--mu:#cbbfe6;--ac:#e6d4ff;\n  --card:rgba(255,255,255,.07);--line:rgba(255,255,255,.22);\n  --btn:linear-gradient(135deg,#a77af2,#d58ccf);--on-btn:#fff;--glow:rgba(167,122,242,.45);\n  --s-soft:rgba(255,159,207,.28);--p-soft:rgba(167,122,242,.25);\n  --paper:#f7f0e4;--ink:#2a2033;--sky1:#070516;--sky2:#1a1245;--sky-star:#f1e6ff;\n  --sans:system-ui,-apple-system,\"Segoe UI\",Roboto,\"Helvetica Neue\",Arial,sans-serif;\n  --script:\"Segoe Script\",\"Snell Roundhand\",\"Apple Chancery\",\"Brush Script MT\",\"Lucida Handwriting\",cursive;\n  --hand:\"Segoe Print\",\"Bradley Hand\",\"Chalkboard SE\",\"Marker Felt\",\"Comic Sans MS\",cursive;\n}\n*{box-sizing:border-box}\n[hidden]{display:none!important}\nhtml{scroll-behavior:smooth;-webkit-text-size-adjust:100%}\nbody{margin:0;background:var(--bg);color:var(--tx);font:16px/1.6 var(--sans);overflow-x:hidden}\n#app{min-height:100vh;background:linear-gradient(170deg,var(--bg),var(--bg2))}\nimg{max-width:100%}\n.btn{background:var(--btn);color:var(--on-btn);border:0;border-radius:999px;padding:13px 34px;font:700 16px/1 var(--sans);cursor:pointer;box-shadow:0 10px 26px -10px var(--glow);transition:transform .15s}\n.btn:hover{transform:translateY(-1px)}\n.btn:focus-visible,.pl-btn:focus-visible{outline:3px solid var(--ac);outline-offset:3px}\n\n/* ===== 2. Açılış ===== */\n.intro{position:fixed;inset:0;z-index:100;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:24px;background:radial-gradient(circle at 50% 38%,var(--p-soft),transparent 60%),linear-gradient(170deg,var(--bg),var(--bg2));transition:opacity .8s,visibility .8s}\n.intro.hide{opacity:0;visibility:hidden}\n.intro-heart{font-size:84px;line-height:1;color:var(--p);filter:drop-shadow(0 0 22px var(--glow));animation:pulse 1.3s ease-in-out infinite}\n@keyframes pulse{50%{transform:scale(1.12)}}\n.intro-title{font:400 clamp(2rem,8vw,2.9rem)/1.2 var(--script);margin:18px 0 4px;color:var(--ac)}\n.intro-sub{color:var(--mu);margin:0 0 6px}\n.intro .btn{margin-top:18px}\n\n/* ===== 3. Hero ===== */\n.hero{position:relative;min-height:100vh;min-height:100svh;display:grid;place-items:center;padding:40px 18px;text-align:center;overflow:hidden}\n.hero-bg{position:absolute;inset:0;background:radial-gradient(60% 46% at 50% 34%,var(--p-soft),transparent 72%),radial-gradient(40% 30% at 85% 85%,var(--s-soft),transparent 70%);background-size:cover;background-position:center}\n.has-img .hero-bg{background-size:cover;background-position:center}\n.has-img .hero-bg::after{content:\"\";position:absolute;inset:0;background:linear-gradient(180deg,var(--bg),var(--bg2));opacity:.7}\n.hero-in{position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;max-width:640px}\n.names{margin:0;letter-spacing:.2em;text-transform:uppercase;color:var(--ac);font-size:.85rem}\n.hero-title{font:400 clamp(2.6rem,10vw,4.8rem)/1.12 var(--script);margin:14px 0 10px;color:var(--tx);text-shadow:0 0 28px var(--glow);white-space:pre-line;overflow-wrap:anywhere}\n.hero-text{max-width:520px;margin:0;color:var(--mu);line-height:1.75;white-space:pre-line}\n.counter{display:flex;justify-content:center;flex-wrap:wrap;gap:10px;margin-top:30px}\n.unit{min-width:76px;padding:13px 8px;border:1px solid var(--line);border-radius:16px;background:var(--card);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px)}\n.unit b{display:block;font-size:1.6rem;font-variant-numeric:tabular-nums;color:var(--tx)}\n.unit span{font-size:.68rem;letter-spacing:.08em;text-transform:uppercase;color:var(--mu)}\n.since{margin:16px 0 0;color:var(--ac);font-size:.88rem}\n.met{margin-top:16px;max-width:340px;padding:12px 18px;border:1px dashed var(--line);border-radius:16px;background:var(--card);color:var(--mu);font-size:.88rem;white-space:pre-line}\n.met b{color:var(--tx)}\n\n/* ===== 4. Albüm - ortak ===== */\n.album{position:relative;padding:76px 16px 96px;overflow:hidden}\n.atmo{position:absolute;inset:0;z-index:0;pointer-events:none}\n.album-in{position:relative;z-index:1;max-width:1080px;margin:0 auto}\n.album-title{font:400 clamp(2.2rem,7vw,3.4rem)/1.2 var(--script);text-align:center;margin:0 0 30px;color:var(--ac);overflow-wrap:anywhere}\n.gal{position:relative}\n.ph{margin:0;position:relative}\n.frame{position:relative}\n.frame img{display:block;width:100%;height:auto;cursor:zoom-in}\n.frame i{display:none}\nfigcaption{overflow-wrap:anywhere}\n.foot{text-align:center;color:var(--ac);padding:34px 16px 60px;font:400 1.35rem/1.4 var(--script);white-space:pre-line}\n\n/* ===== 5. Kayan yıldızlar ===== */\n.mem-stars{background:radial-gradient(ellipse at 50% 0,var(--sky2),transparent 75%),var(--sky1);color:#f3eeff}\n.mem-stars .album-title{color:#fff;text-shadow:0 0 24px var(--glow)}\n.star{position:absolute;border-radius:50%;background:var(--sky-star);opacity:.25;animation:twinkle 3s ease-in-out infinite alternate}\n@keyframes twinkle{to{opacity:1;transform:scale(1.5)}}\n.star.spark{background:none;border-radius:0;width:12px!important;height:12px!important}\n.star.spark::before,.star.spark::after{content:\"\";position:absolute;left:50%;top:50%;background:#fff;transform:translate(-50%,-50%);box-shadow:0 0 8px 1px #fff}\n.star.spark::before{width:100%;height:1px}.star.spark::after{width:1px;height:100%}\n.meteor{position:absolute;width:120px;height:2px;border-radius:2px;background:linear-gradient(90deg,transparent,#fff);opacity:0;animation:shoot 10s linear infinite}\n@keyframes shoot{0%{opacity:0;transform:translate(0,0) rotate(33deg)}2%{opacity:1}9%{opacity:0;transform:translate(300px,195px) rotate(33deg)}100%{opacity:0;transform:translate(300px,195px) rotate(33deg)}}\n.mem-stars .gal{display:grid;grid-template-columns:repeat(3,1fr);gap:40px 22px;padding-top:24px}\n.mem-stars .ph:nth-child(3n+2){margin-top:48px}\n.mem-stars .ph:nth-child(3n){margin-top:18px}\n.mem-stars .frame{aspect-ratio:3/4;border-radius:50% 50% 16px 16px/36% 36% 16px 16px;border:1.5px solid rgba(255,255,255,.55);box-shadow:0 0 0 7px rgba(255,255,255,.05),0 0 36px var(--glow),0 0 90px -10px var(--s-soft);animation:float 7s ease-in-out infinite alternate;animation-delay:var(--d)}\n.mem-stars .frame img{height:100%;object-fit:cover;border-radius:inherit}\n@keyframes float{to{transform:translateY(-9px)}}\n.mem-stars .d1{display:block;position:absolute;top:7%;right:-7px;width:16px;height:16px;background:var(--sky-star);clip-path:polygon(50% 0,62% 38%,100% 50%,62% 62%,50% 100%,38% 62%,0 50%,38% 38%);filter:drop-shadow(0 0 5px #fff);animation:twinkle 2.4s ease-in-out infinite alternate}\n.mem-stars .d2{display:block;position:absolute;bottom:14%;left:-6px;width:9px;height:9px;background:var(--s);clip-path:polygon(50% 0,62% 38%,100% 50%,62% 62%,50% 100%,38% 62%,0 50%,38% 38%);animation:twinkle 3.2s ease-in-out infinite alternate}\n.mem-stars figcaption{margin-top:16px;text-align:center;font-size:.92rem;color:#e9e0ff;letter-spacing:.02em;text-shadow:0 0 12px var(--glow)}\n.mem-stars figcaption::before{content:\"✦ \";color:var(--s)}\n\n/* ===== 6. Mandallı fotoğraflar ===== */\n.mem-clothesline{background:radial-gradient(ellipse at 50% -5%,rgba(255,196,110,.28),transparent 58%),linear-gradient(180deg,var(--bg2),var(--bg))}\n.mem-clothesline .atmo::before{content:\"\";position:absolute;left:-2%;right:-2%;top:22px;height:2px;background:rgba(120,88,52,.8);border-radius:50%/100%;box-shadow:0 2px 3px rgba(0,0,0,.35)}\n.bulb{position:absolute;width:9px;height:13px;border-radius:50% 50% 48% 48%/60% 60% 40% 40%;background:#ffe2a0;box-shadow:0 0 10px 4px rgba(255,205,110,.75),0 0 38px 12px rgba(255,170,70,.28);animation:flick 3.4s ease-in-out infinite alternate}\n@keyframes flick{0%{opacity:.7}40%{opacity:1}100%{opacity:.82}}\n.mem-clothesline .album-title{padding-top:26px;text-shadow:0 0 22px rgba(255,200,120,.45)}\n.mem-clothesline .gal{display:grid;grid-template-columns:repeat(3,1fr);row-gap:64px;column-gap:0;align-items:start;padding-top:10px}\n.mem-clothesline .ph{padding:36px 14px 0}\n.mem-clothesline .ph::before{content:\"\";position:absolute;left:0;right:0;top:20px;height:3px;background:repeating-linear-gradient(115deg,#8b6b44 0 3px,#b08a5a 3px 6px);box-shadow:0 3px 4px rgba(0,0,0,.4)}\n.mem-clothesline .frame{background:#fff8eb;padding:9px;border-radius:2px;box-shadow:0 16px 26px -12px rgba(0,0,0,.65),0 0 0 1px rgba(90,60,30,.15);transform-origin:50% -14px;animation:sway 6.5s ease-in-out infinite alternate;animation-delay:var(--d)}\n@keyframes sway{from{transform:rotate(calc(var(--r) * .35 - 1.4deg))}to{transform:rotate(calc(var(--r) * .35 + 1.4deg))}}\n.mem-clothesline .frame img{filter:sepia(.14) saturate(1.06)}\n.mem-clothesline .frame::after{content:\"\";position:absolute;inset:9px;background:radial-gradient(circle at 50% -10%,rgba(255,215,150,.38),transparent 62%);pointer-events:none}\n.mem-clothesline .d1{display:block;position:absolute;top:-24px;left:50%;width:15px;height:38px;transform:translateX(-50%);border-radius:3px 3px 2px 2px;background:linear-gradient(90deg,#e0bd88,#b98d52 55%,#e0bd88);box-shadow:0 3px 4px rgba(0,0,0,.45);z-index:2}\n.mem-clothesline .d1::after{content:\"\";position:absolute;left:2px;right:2px;top:16px;height:3px;background:#6b6f78;border-radius:2px}\n.mem-clothesline figcaption{display:table;margin:14px auto 0;padding:5px 14px 5px 22px;background:#ead6ad;color:#5b4128;font:400 .98rem/1.3 var(--hand);border-radius:2px 9px 9px 2px;position:relative;box-shadow:0 4px 8px -4px rgba(0,0,0,.5);text-align:center}\n.mem-clothesline figcaption::before{content:\"\";position:absolute;left:7px;top:50%;width:6px;height:6px;margin-top:-3px;border-radius:50%;background:var(--bg2);box-shadow:inset 0 1px 1px rgba(0,0,0,.5)}\n\n/* ===== 7. Anı defteri ===== */\n.mem-scrapbook{background:linear-gradient(170deg,var(--bg2),var(--bg));padding-left:10px;padding-right:10px}\n.mem-scrapbook .album-in{background-color:var(--paper);color:var(--ink);padding:46px clamp(16px,4vw,46px) 30px clamp(30px,6vw,64px);border-radius:6px;box-shadow:0 34px 60px -24px rgba(0,0,0,.6),0 0 0 1px rgba(0,0,0,.06);\n  background-image:linear-gradient(90deg,transparent 52px,rgba(214,90,100,.3) 52px,rgba(214,90,100,.3) 54px,transparent 54px),repeating-linear-gradient(transparent 0 33px,rgba(80,110,160,.16) 33px 34px),url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='2' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 .4 0 0 0 0 .3 0 0 0 0 .2 0 0 0 .08 0'/></filter><rect width='160' height='160' filter='url(%23n)'/></svg>\")}\n.mem-scrapbook .album-in::before{content:\"\";position:absolute;left:12px;top:20px;bottom:20px;width:14px;background:radial-gradient(circle,rgba(40,30,30,.45) 4px,transparent 5px) 0 0/14px 38px repeat-y}\n.mem-scrapbook .album-title{color:var(--ink);font-family:var(--hand);font-size:clamp(1.9rem,6vw,2.8rem);display:table;margin:0 auto 34px;border-bottom:3px dotted var(--p);padding:0 12px 4px}\n.mem-scrapbook .gal{display:grid;grid-template-columns:repeat(3,1fr);gap:26px 30px;align-items:start}\n.mem-scrapbook .ph{margin:0 0 6px;transform:rotate(var(--r))}\n.mem-scrapbook .frame{background:#fff;padding:9px;box-shadow:0 7px 14px -7px rgba(70,45,20,.55),0 0 0 1px rgba(0,0,0,.05)}\n.mem-scrapbook .d1{display:block;position:absolute;top:-13px;left:50%;width:88px;height:24px;transform:translateX(-50%) rotate(calc(var(--r) * -1.6));background:repeating-linear-gradient(135deg,var(--s) 0 7px,rgba(255,255,255,.55) 7px 14px);opacity:.72;box-shadow:0 1px 2px rgba(0,0,0,.18);clip-path:polygon(0 8%,4% 0,8% 8%,12% 0,16% 8%,20% 0,24% 8%,28% 0,32% 8%,36% 0,40% 8%,44% 0,48% 8%,52% 0,56% 8%,60% 0,64% 8%,68% 0,72% 8%,76% 0,80% 8%,84% 0,88% 8%,92% 0,96% 8%,100% 0,100% 92%,96% 100%,92% 92%,88% 100%,84% 92%,80% 100%,76% 92%,72% 100%,68% 92%,64% 100%,60% 92%,56% 100%,52% 92%,48% 100%,44% 92%,40% 100%,36% 92%,32% 100%,28% 92%,24% 100%,20% 92%,16% 100%,12% 92%,8% 100%,4% 92%,0 100%)}\n.mem-scrapbook .ph:nth-child(3n+2) .d1{top:-9px;left:-10px;transform:rotate(-38deg);width:70px}\n.mem-scrapbook .ph:nth-child(3n) .d1{left:auto;right:-14px;top:-6px;transform:rotate(36deg);width:70px;background:repeating-linear-gradient(90deg,var(--p) 0 6px,rgba(255,255,255,.55) 6px 12px)}\n.mem-scrapbook .d2{display:block;position:absolute;right:2px;bottom:2px;width:26px;height:26px;background:linear-gradient(135deg,transparent 50%,rgba(60,45,35,.8) 50%)}\n.mem-scrapbook figcaption{margin-top:10px;font:400 1.08rem/1.35 var(--hand);color:var(--ink);text-align:center}\n.mem-scrapbook .ph:nth-child(3n+1) figcaption{background:rgba(255,232,140,.92);padding:7px 10px;transform:rotate(-1.6deg);box-shadow:0 4px 8px -4px rgba(0,0,0,.4);margin:12px 6px 0}\n.mem-scrapbook .ph:nth-child(4n)::after{content:\"♥\";position:absolute;right:-6px;bottom:34px;color:var(--p);font-size:1.5rem;transform:rotate(14deg);text-shadow:0 1px 0 rgba(255,255,255,.7)}\n.mem-scrapbook .foot,.mem-scrapbook ~ .foot{color:var(--ac)}\n\n/* ===== 8. Polaroid duvarı ===== */\n.mem-polaroid{background:radial-gradient(ellipse at 50% 18%,rgba(255,244,225,.14),transparent 60%),repeating-linear-gradient(90deg,rgba(255,255,255,.025) 0 2px,transparent 2px 30px),var(--bg2);box-shadow:inset 0 0 170px rgba(0,0,0,.42)}\n.mem-polaroid .album-in{max-width:1000px}\n.mem-polaroid .gal{display:flex;flex-wrap:wrap;justify-content:center;padding:14px 0 10px}\n.mem-polaroid .ph{width:min(46%,250px);margin:-4px -2px 26px;padding:12px 12px 12px;background:#fdfcf8;transform:rotate(var(--r));box-shadow:0 1px 2px rgba(0,0,0,.4),0 20px 32px -10px rgba(0,0,0,.7),0 0 0 1px rgba(0,0,0,.08)}\n.mem-polaroid .ph:nth-child(even){margin-top:26px}\n.mem-polaroid .ph:nth-child(3n){margin-left:-12px}\n.mem-polaroid .frame{aspect-ratio:1/1;background:#222}\n.mem-polaroid .frame img{height:100%;object-fit:cover;filter:contrast(1.04) saturate(1.08)}\n.mem-polaroid .frame::after{content:\"\";position:absolute;inset:0;box-shadow:inset 0 0 22px rgba(0,0,0,.32);pointer-events:none}\n.mem-polaroid .d1{display:block;position:absolute;top:-24px;left:50%;width:16px;height:16px;margin-left:-8px;border-radius:50%;background:radial-gradient(circle at 34% 30%,#fff 0 11%,var(--s) 14% 58%,var(--p) 100%);box-shadow:0 5px 6px rgba(0,0,0,.55);z-index:2}\n.mem-polaroid figcaption{min-height:46px;padding-top:11px;text-align:center;color:#2c2a35;font:400 1.02rem/1.3 var(--hand)}\n\n/* ===== 9. Cam kartlar ===== */\n.mem-glass{background:linear-gradient(170deg,var(--bg),var(--bg2))}\n.mem-glass .atmo{inset:-12%;background:radial-gradient(circle at 14% 18%,var(--p) 0,transparent 36%),radial-gradient(circle at 88% 34%,var(--s) 0,transparent 38%),radial-gradient(circle at 38% 92%,var(--p-soft) 0,transparent 44%);opacity:.55;filter:blur(36px);animation:orbs 24s ease-in-out infinite alternate}\n@keyframes orbs{to{transform:translate3d(3%,-4%,0) scale(1.08)}}\n.mem-glass .gal{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}\n.mem-glass .ph{padding:10px;border-radius:28px;background:linear-gradient(145deg,rgba(255,255,255,.24),rgba(255,255,255,.06));-webkit-backdrop-filter:blur(18px) saturate(150%);backdrop-filter:blur(18px) saturate(150%);border:1px solid rgba(255,255,255,.32);box-shadow:0 24px 50px -22px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,255,255,.5)}\n.mem-glass .ph:nth-child(5n+1){grid-column:span 2}\n.mem-glass .frame{border-radius:20px;overflow:hidden;aspect-ratio:4/5}\n.mem-glass .ph:nth-child(5n+1) .frame{aspect-ratio:16/10}\n.mem-glass .frame img{height:100%;object-fit:cover}\n.mem-glass .d1{display:block;position:absolute;inset:0;background:radial-gradient(circle at 18% 0,rgba(255,255,255,.42),transparent 52%);pointer-events:none}\n.mem-glass figcaption{padding:11px 8px 4px;color:var(--tx);font-size:.92rem;text-align:center}\n[data-mode=light] .mem-glass .ph{background:linear-gradient(145deg,rgba(255,255,255,.75),rgba(255,255,255,.38));border-color:rgba(255,255,255,.85);box-shadow:0 22px 44px -22px rgba(80,60,100,.35),inset 0 1px 0 #fff}\n[data-mode=light] .mem-glass .atmo{opacity:.7}\n\n/* ===== 10. Müzik oynatıcı & büyük görsel ===== */\n.player{position:fixed;left:14px;bottom:calc(14px + env(safe-area-inset-bottom,0px));z-index:40;display:flex;align-items:center;gap:10px;max-width:calc(100% - 28px);padding:7px 16px 7px 7px;border-radius:999px;background:var(--card);border:1px solid var(--line);-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);box-shadow:0 12px 30px -14px rgba(0,0,0,.6)}\n[data-mode=light] .player{background:rgba(255,255,255,.8)}\n.pl-btn{flex:none;width:40px;height:40px;border:0;border-radius:50%;background:var(--btn);color:var(--on-btn);font-size:13px;cursor:pointer;display:grid;place-items:center}\n.pl-meta{display:flex;align-items:center;gap:9px;min-width:0}\n.pl-title{font-size:.85rem;color:var(--tx);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:46vw}\n.pl-bars{display:inline-flex;align-items:flex-end;gap:2px;height:14px}\n.pl-bars i{width:3px;height:4px;border-radius:2px;background:var(--p)}\n.playing .pl-bars i{animation:bar .9s ease-in-out infinite alternate}\n.playing .pl-bars i:nth-child(2){animation-delay:.2s}.playing .pl-bars i:nth-child(3){animation-delay:.45s}.playing .pl-bars i:nth-child(4){animation-delay:.1s}\n@keyframes bar{to{height:14px}}\n.lightbox{position:fixed;inset:0;z-index:90;background:rgba(8,6,16,.9);display:flex;flex-direction:column;align-items:center;justify-content:center;padding:20px;cursor:zoom-out}\n.lightbox img{max-width:100%;max-height:78vh;border-radius:8px;box-shadow:0 30px 80px rgba(0,0,0,.6)}\n.lightbox p{color:#f1ebff;margin:14px 0 0;text-align:center}\n.lb-close{position:absolute;top:12px;right:16px;border:0;background:none;color:#fff;font-size:38px;cursor:pointer}\n\n/* ===== 11. Mobil ve hareket tercihi ===== */\n@media(max-width:760px){\n  .mem-stars .gal{grid-template-columns:repeat(2,1fr);gap:30px 14px}\n  .mem-stars .ph:nth-child(3n+2),.mem-stars .ph:nth-child(3n){margin-top:0}.mem-stars .ph:nth-child(even){margin-top:38px}\n  .mem-clothesline .gal{grid-template-columns:repeat(2,1fr)}\n  .mem-clothesline .ph{padding-left:8px;padding-right:8px}\n  .mem-glass .gal{grid-template-columns:repeat(2,1fr);gap:12px}\n  .mem-glass .ph{border-radius:22px;padding:7px;-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px)}\n  .mem-glass .frame{border-radius:16px}\n  .mem-glass .atmo{filter:blur(24px);animation:none}\n  .mem-polaroid .ph{width:min(47%,220px);padding:9px 9px 9px}\n  .mem-scrapbook .album-in{padding-left:34px}\n  .mem-scrapbook .gal{grid-template-columns:repeat(2,1fr);gap:22px 14px}\n  .mem-scrapbook .frame{padding:6px}\n  .album{padding:60px 12px 80px}\n}\n@media(prefers-reduced-motion:reduce){\n  *,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}\n  .intro-heart{animation:none}\n}\n","js":"/* Love Panel 3.0 - Site motoru\n * window.LOVE_CONFIG (js/config.js) verisinden siteyi çizer.\n * Panel önizlemesi de bu dosyanın aynısını kullanır: LoveSite.update(config)\n */\n(function (root) {\n  'use strict';\n  var D = document;\n\n  /* ---------- küçük yardımcılar ---------- */\n  function el(tag, cls, txt) { var e = D.createElement(tag); if (cls) e.className = cls; if (txt != null) e.textContent = txt; return e; }\n  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }\n\n  /* ---------- renk matematiği ---------- */\n  function parseHex(h) {\n    h = String(h || '').trim().replace(/^#/, '');\n    if (h.length === 3) h = h.replace(/./g, '$&$&');\n    if (!/^[0-9a-f]{6}$/i.test(h)) return null;\n    return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];\n  }\n  function rgb2hsl(r, g, b) {\n    r /= 255; g /= 255; b /= 255;\n    var mx = Math.max(r, g, b), mn = Math.min(r, g, b), l = (mx + mn) / 2, h = 0, s = 0, d = mx - mn;\n    if (d) {\n      s = l > 0.5 ? d / (2 - mx - mn) : d / (mx + mn);\n      h = mx === r ? (g - b) / d + (g < b ? 6 : 0) : mx === g ? (b - r) / d + 2 : (r - g) / d + 4;\n      h *= 60;\n    }\n    return [h, s * 100, l * 100];\n  }\n  function hsl2rgb(h, s, l) {\n    s /= 100; l /= 100;\n    var k = function (n) { return (n + h / 30) % 12; }, a = s * Math.min(l, 1 - l);\n    var f = function (n) { return l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1))); };\n    return [Math.round(f(0) * 255), Math.round(f(8) * 255), Math.round(f(4) * 255)];\n  }\n  function hsl(h, s, l, a) {\n    h = Math.round(h); s = Math.round(s); l = Math.round(l);\n    return a == null ? 'hsl(' + h + ',' + s + '%,' + l + '%)' : 'hsla(' + h + ',' + s + '%,' + l + '%,' + a + ')';\n  }\n  function lum(c) {\n    var f = function (v) { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };\n    return 0.2126 * f(c[0]) + 0.7152 * f(c[1]) + 0.0722 * f(c[2]);\n  }\n  function contrast(a, b) { var x = lum(a), y = lum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); }\n  function rgbCss(c, a) { return a == null ? 'rgb(' + c.join(',') + ')' : 'rgba(' + c.join(',') + ',' + a + ')'; }\n  function mixRgb(a, b, t) { return [0, 1, 2].map(function (i) { return Math.round(a[i] + (b[i] - a[i]) * t); }); }\n\n  /* ---------- tema: iki renkten tüm değişkenler ---------- */\n  function computeTheme(t) {\n    t = t || {};\n    var p = parseHex(t.primary) || [167, 122, 242], s = parseHex(t.secondary) || [255, 159, 207];\n    var P = rgb2hsl(p[0], p[1], p[2]), S = rgb2hsl(s[0], s[1], s[2]);\n    var dark = t.mode !== 'light', v = {}, pv, sv;\n    if (dark) {\n      pv = [P[0], clamp(P[1], 35, 100), clamp(P[2], 50, 68)];\n      sv = [S[0], clamp(S[1], 30, 100), clamp(S[2], 66, 86)];\n      v.bg = hsl(P[0], clamp(P[1] * 0.6, 28, 55), 7);\n      v.bg2 = hsl(S[0], clamp(S[1] * 0.5, 24, 50), 15);\n      v.tx = hsl(S[0], 35, 95); v.mu = hsl(S[0], 24, 80);\n      v.ac = hsl(S[0], clamp(S[1], 35, 100), clamp(S[2], 78, 88));\n      v.card = 'rgba(255,255,255,.07)'; v.line = hsl(sv[0], sv[1], sv[2], 0.28);\n      v.paper = hsl(S[0], 32, 93); v.ink = hsl(P[0], 38, 17);\n    } else {\n      pv = [P[0], clamp(P[1], 28, 85), clamp(P[2], 34, 56)];\n      sv = [S[0], clamp(S[1], 30, 90), clamp(S[2], 70, 88)];\n      v.bg = hsl(S[0], clamp(S[1], 30, 70), 95); v.bg2 = hsl(P[0], clamp(P[1] * 0.6, 28, 60), 91);\n      v.tx = hsl(P[0], 32, 15); v.mu = hsl(P[0], 20, 33);\n      v.ac = hsl(P[0], clamp(P[1], 30, 80), clamp(P[2], 28, 40));\n      v.card = 'rgba(255,255,255,.66)'; v.line = hsl(pv[0], pv[1], pv[2], 0.3);\n      v.paper = hsl(S[0], clamp(S[1], 30, 60), 96); v.ink = hsl(P[0], 34, 20);\n    }\n    var pr = hsl2rgb(pv[0], pv[1], pv[2]), sr = hsl2rgb(sv[0], sv[1], sv[2]);\n    var end = mixRgb(pr, sr, 0.6), white = [255, 255, 255], deep = [28, 18, 40];\n    var onBtn = Math.min(contrast(pr, white), contrast(end, white)) >= Math.min(contrast(pr, deep), contrast(end, deep)) ? white : deep;\n    v.p = rgbCss(pr); v.s = rgbCss(sr);\n    v.btn = 'linear-gradient(135deg,' + rgbCss(pr) + ',' + rgbCss(end) + ')';\n    v['on-btn'] = rgbCss(onBtn); v.glow = rgbCss(pr, 0.45); v['s-soft'] = rgbCss(sr, 0.28); v['p-soft'] = rgbCss(pr, 0.25);\n    v.sky1 = hsl(P[0], clamp(P[1] * 0.7, 35, 60), 5); v.sky2 = hsl(S[0], clamp(S[1] * 0.55, 30, 55), 15);\n    v['sky-star'] = hsl(S[0], 70, 90);\n    var hp = hsl2rgb(pv[0], pv[1], dark ? Math.max(pv[2], 66) : Math.min(pv[2], 52));  // kalpler zeminden ayrışsın\n    v._hearts = { primary: rgbCss(hp), secondary: rgbCss(sr), white: '#ffffff' };\n    v._dark = dark;\n    return v;\n  }\n\n  /* ---------- örnek fotoğraflar (yalnızca panel önizlemesi için) ---------- */\n  function sampleSvg(w, h, c1, c2, n) {\n    var s = '<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 ' + w + ' ' + h + '\"><defs><linearGradient id=\"g\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop offset=\"0\" stop-color=\"' + c1 + '\"/><stop offset=\"1\" stop-color=\"' + c2 + '\"/></linearGradient></defs><rect width=\"' + w + '\" height=\"' + h + '\" fill=\"url(#g)\"/><circle cx=\"' + w * 0.72 + '\" cy=\"' + h * 0.28 + '\" r=\"' + w * 0.09 + '\" fill=\"#fff\" opacity=\".35\"/><path d=\"M0 ' + h * 0.85 + ' Q' + w * 0.3 + ' ' + h * 0.55 + ' ' + w * 0.55 + ' ' + h * 0.8 + ' T' + w + ' ' + h * 0.7 + ' V' + h + ' H0Z\" fill=\"#000\" opacity=\".18\"/><text x=\"50%\" y=\"52%\" text-anchor=\"middle\" font-size=\"' + w * 0.2 + '\" fill=\"#fff\" opacity=\".85\">&#9829;</text></svg>';\n    return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(s);\n  }\n  function samplePhotos(v) {\n    var a = v.p, b = v.s, dims = [[800, 1000], [900, 900], [1000, 680], [800, 1000], [800, 1060], [900, 900]];\n    var caps = ['İlk buluşmamız', 'Birlikte gülerken', 'Yaz tatili', 'Sürpriz kutlama', 'Gün batımı', 'Bizim fotoğrafımız'];\n    return dims.map(function (d, i) { return { src: sampleSvg(d[0], d[1], i % 2 ? b : a, i % 2 ? a : b), caption: caps[i], sample: true }; });\n  }\n\n  /* ---------- site ---------- */\n  var S = { app: null, cfg: null, hearts: null, tickTimer: 0, photoSig: '', audioSrc: null, started: false, firstGesture: false };\n  var MEMORIES = ['stars', 'clothesline', 'scrapbook', 'polaroid', 'glass'];\n\n  function build() {\n    var app = el('div'); app.id = 'app';\n    app.innerHTML =\n      '<div class=\"intro\" id=\"intro\" role=\"dialog\" aria-live=\"polite\"><div class=\"intro-heart\" aria-hidden=\"true\">♥</div><h2 class=\"intro-title\"></h2><p class=\"intro-sub\"></p><button type=\"button\" class=\"btn\" id=\"introBtn\"></button></div>' +\n      '<main>' +\n      '<header class=\"hero\" id=\"hero\"><div class=\"hero-bg\"></div><div class=\"hero-in\">' +\n      '<p class=\"names\"></p><h1 class=\"hero-title\"></h1><p class=\"hero-text\"></p>' +\n      '<div class=\"counter\" aria-label=\"Birlikte geçen zaman\"><div class=\"unit\"><b data-u=\"d\">0</b><span>Gün</span></div><div class=\"unit\"><b data-u=\"h\">0</b><span>Saat</span></div><div class=\"unit\"><b data-u=\"m\">0</b><span>Dakika</span></div><div class=\"unit\"><b data-u=\"s\">0</b><span>Saniye</span></div></div>' +\n      '<p class=\"since\">♥ Birlikte geçen zaman ♥</p><div class=\"met\" hidden></div></div></header>' +\n      '<section class=\"album\" id=\"album\"><div class=\"atmo\" aria-hidden=\"true\"></div><div class=\"album-in\"><h2 class=\"album-title\"></h2><div class=\"gal\"></div></div></section>' +\n      '</main><footer class=\"foot\"></footer>' +\n      '<div class=\"player\" hidden><button type=\"button\" class=\"pl-btn\" aria-label=\"Müziği oynat / duraklat\">▶</button><div class=\"pl-meta\"><span class=\"pl-title\"></span><span class=\"pl-bars\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i></span></div></div>' +\n      '<audio id=\"audio\" loop preload=\"metadata\"></audio>' +\n      '<div class=\"lightbox\" hidden><button type=\"button\" class=\"lb-close\" aria-label=\"Kapat\">×</button><img alt=\"\"><p></p></div>';\n    D.body.appendChild(app);\n    S.app = app;\n    S.hearts = root.LoveHearts ? root.LoveHearts() : null;\n\n    $('#introBtn').addEventListener('click', function () { hideIntro(); startMusic(); });\n    $('.pl-btn').addEventListener('click', toggleMusic);\n    $('#audio').addEventListener('play', syncPlayer); $('#audio').addEventListener('pause', syncPlayer);\n    $('.lightbox').addEventListener('click', closeLightbox);\n    D.addEventListener('keydown', function (e) { if (e.key === 'Escape') closeLightbox(); });\n    $('.gal').addEventListener('click', function (e) {\n      var img = e.target.closest && e.target.closest('.frame img'); if (!img) return;\n      var lb = $('.lightbox'); lb.querySelector('img').src = img.src; lb.querySelector('p').textContent = img.alt || ''; lb.hidden = false;\n    });\n    var first = function () {\n      if (S.firstGesture) return; S.firstGesture = true;\n      if (S.cfg && !S.cfg.preview && !S.cfg.intro.enabled) startMusic();\n    };\n    D.addEventListener('pointerdown', first, { once: true });\n    setInterval(tick, 1000);\n  }\n  function $(sel) { return S.app.querySelector(sel); }\n  function closeLightbox() { var lb = $('.lightbox'); if (lb) lb.hidden = true; }\n  function hideIntro() { $('#intro').classList.add('hide'); }\n\n  /* müzik */\n  function audio() { return $('#audio'); }\n  function startMusic() {\n    var c = S.cfg; if (!c || c.preview || !c.music.enabled || !c.music.src || !c.music.autoplay) return;\n    audio().play().catch(function () {});\n  }\n  function toggleMusic() { var a = audio(); if (!a.src) return; if (a.paused) a.play().catch(function () {}); else a.pause(); }\n  function syncPlayer() { var pl = $('.player'), a = audio(); pl.classList.toggle('playing', !a.paused); $('.pl-btn').textContent = a.paused ? '▶' : '❚❚'; }\n\n  /* sayaç */\n  function parseDate(v) { if (!v) return null; var p = String(v).split('-').map(Number); if (p.length < 3 || p.some(isNaN)) return null; return new Date(p[0], p[1] - 1, p[2], 0, 0, 0); }\n  function tick() {\n    if (!S.cfg) return;\n    var st = parseDate(S.cfg.startDate), t = st ? Math.max(0, Math.floor((Date.now() - st.getTime()) / 1000)) : 0;\n    var vals = { d: Math.floor(t / 86400), h: Math.floor(t % 86400 / 3600), m: Math.floor(t % 3600 / 60), s: t % 60 };\n    Object.keys(vals).forEach(function (k) { var b = S.app.querySelector('[data-u=\"' + k + '\"]'); if (b && b.textContent !== String(vals[k])) b.textContent = vals[k]; });\n    var met = parseDate(S.cfg.metDate), box = $('.met');\n    if (S.cfg.showMet && met) {\n      var md = Math.max(0, Math.floor((Date.now() - met.getTime()) / 86400000));\n      var n = box.querySelector('b'); if (n && n.textContent !== String(md)) n.textContent = md;\n    }\n  }\n\n  /* albüm */\n  function renderPhotos(list) {\n    var gal = $('.gal'), sig = list.map(function (p) { return p.src; }).join('|');\n    if (sig === S.photoSig) {   // yalnızca açıklama değişti: görselleri yeniden yükleme\n      var caps = gal.querySelectorAll('figcaption'), imgs = gal.querySelectorAll('img');\n      list.forEach(function (p, i) { if (caps[i]) caps[i].textContent = p.caption || ''; if (caps[i]) caps[i].hidden = !p.caption; if (imgs[i]) imgs[i].alt = p.caption || ''; });\n      return;\n    }\n    S.photoSig = sig; gal.textContent = '';\n    var tilts = [-3.2, 2.4, -1.4, 3.4, -2.2, 1.6, -3.6, 2.8, -.8, 1.2];\n    list.forEach(function (p, i) {\n      var fig = el('figure', 'ph');\n      fig.style.setProperty('--i', i); fig.style.setProperty('--r', tilts[i % tilts.length] + 'deg');\n      fig.style.setProperty('--d', ((i * 0.37) % 2.4).toFixed(2) + 's');\n      var fr = el('div', 'frame'), img = el('img'); img.src = p.src; img.alt = p.caption || ''; img.loading = 'lazy'; img.decoding = 'async';\n      fr.appendChild(img); fr.appendChild(el('i', 'd1')); fr.appendChild(el('i', 'd2'));\n      var cap = el('figcaption', null, p.caption || ''); cap.hidden = !p.caption;\n      fig.appendChild(fr); fig.appendChild(cap); gal.appendChild(fig);\n    });\n  }\n\n  /* kayan yıldız atmosferi (sabit tohumlu: önizleme = gerçek site) */\n  function buildStars() {\n    var at = $('.atmo'); if (at.dataset.kind === 'stars') return;\n    at.textContent = ''; at.dataset.kind = 'stars';\n    var seed = 7, rnd = function () { seed = (seed * 16807) % 2147483647; return seed / 2147483647; };\n    for (var i = 0; i < 70; i++) {\n      var s = el('i', 'star'); var sz = 1 + rnd() * 2.4;\n      s.style.cssText = 'left:' + (rnd() * 100).toFixed(1) + '%;top:' + (rnd() * 100).toFixed(1) + '%;width:' + sz.toFixed(1) + 'px;height:' + sz.toFixed(1) + 'px;animation-delay:' + (rnd() * 5).toFixed(1) + 's;animation-duration:' + (2.5 + rnd() * 3.5).toFixed(1) + 's';\n      if (i % 9 === 0) s.className = 'star spark';\n      at.appendChild(s);\n    }\n    for (var j = 0; j < 3; j++) { var m = el('i', 'meteor'); m.style.cssText = 'left:' + (20 + j * 28) + '%;top:' + (4 + j * 9) + '%;animation-delay:' + (j * 3.7 + 1) + 's;animation-duration:' + (9 + j * 2) + 's'; at.appendChild(m); }\n  }\n  function buildBulbs() {\n    var at = $('.atmo'); if (at.dataset.kind === 'bulbs') return;\n    at.textContent = ''; at.dataset.kind = 'bulbs';\n    for (var i = 0; i < 16; i++) { var b = el('i', 'bulb'); b.style.cssText = 'left:' + (i * 6.6 + 1).toFixed(1) + '%;top:' + (14 + Math.sin(i * 0.8) * 5 + (i % 2) * 5).toFixed(1) + 'px;animation-delay:' + ((i * 0.43) % 3).toFixed(1) + 's'; at.appendChild(b); }\n  }\n\n  function update(cfg) {\n    if (!S.app) build();\n    S.cfg = cfg;\n    var T = computeTheme(cfg.theme), root_ = D.documentElement;\n    Object.keys(T).forEach(function (k) { if (k.charAt(0) !== '_') root_.style.setProperty('--' + k, T[k]); });\n    root_.setAttribute('data-mode', T._dark ? 'dark' : 'light');\n    D.title = cfg.pageTitle || (cfg.name1 + ' & ' + cfg.name2);\n\n    // açılış\n    var intro = $('#intro'), ie = cfg.intro || {};\n    intro.style.display = ie.enabled ? '' : 'none';\n    intro.querySelector('.intro-title').textContent = ie.title || '';\n    intro.querySelector('.intro-sub').textContent = ie.sub || '';\n    $('#introBtn').textContent = (ie.button || 'Aç') + ' ♥';\n\n    // hero\n    $('.names').textContent = (cfg.name1 || '') + ' & ' + (cfg.name2 || '');\n    $('.hero-title').textContent = cfg.heroTitle || '';\n    $('.hero-text').textContent = cfg.heroText || '';\n    var hb = $('.hero-bg'); hb.style.backgroundImage = cfg.heroImage ? 'url(\"' + cfg.heroImage + '\")' : ''; $('#hero').classList.toggle('has-img', !!cfg.heroImage);\n    var met = $('.met'), showMet = cfg.showMet && parseDate(cfg.metDate);\n    if (showMet) {\n      met.hidden = false;\n      var txt = cfg.metText ? cfg.metText : 'Tanıştığımız günden beri';\n      met.textContent = ''; met.appendChild(D.createTextNode(txt)); met.appendChild(el('br')); met.appendChild(el('b', null, '0')); met.appendChild(D.createTextNode(' gündür hayatımdasın ♥'));\n    } else met.hidden = true;\n\n    // albüm\n    var photos = (cfg.photos && cfg.photos.length) ? cfg.photos : (cfg.samplePhotos ? samplePhotos(T) : []);\n    var album = $('#album'); album.hidden = !photos.length;\n    $('.album-title').textContent = cfg.albumTitle || '';\n    var mem = MEMORIES.indexOf(cfg.memory) > -1 ? cfg.memory : 'stars';\n    album.className = 'album mem-' + mem + (cfg.photos && cfg.photos.length ? '' : ' is-sample');\n    if (mem === 'stars') buildStars(); else if (mem === 'clothesline') buildBulbs(); else { var at = $('.atmo'); at.textContent = ''; at.dataset.kind = ''; }\n    renderPhotos(photos);\n    $('.foot').textContent = cfg.footerText || '';\n\n    // kalpler\n    if (S.hearts) { var hc = cfg.hearts || {}; S.hearts.set({ enabled: !!hc.enabled, color: T._hearts[hc.color] || '#fff', density: hc.density }); }\n\n    // müzik\n    var m = cfg.music || {}, a = audio(), pl = $('.player'), usable = m.enabled && m.src;\n    pl.hidden = !usable;\n    $('.pl-title').textContent = m.title ? '♪ ' + m.title : '♪ Müzik';\n    if (usable) { if (S.audioSrc !== m.src) { S.audioSrc = m.src; a.src = m.src; } }\n    else { if (!a.paused) a.pause(); if (S.audioSrc) { S.audioSrc = null; a.removeAttribute('src'); a.load(); } }\n    syncPlayer();\n\n    tick();\n    if (cfg.preview && !S.introInit) { S.introInit = true; hideIntro(); }\n  }\n\n  root.LoveSite = {\n    update: update, computeTheme: computeTheme,\n    showIntro: function () { $('#intro').classList.remove('hide'); },\n    hideIntro: function () { hideIntro(); },\n    scrollToAlbum: function () { var a = $('#album'); if (a) a.scrollIntoView({ behavior: 'smooth' }); }\n  };\n\n  function boot() { if (root.LOVE_CONFIG) update(root.LOVE_CONFIG); }\n  if (D.readyState === 'loading') D.addEventListener('DOMContentLoaded', boot); else boot();\n})(window);\n","hearts":"/* Love Panel 3.0 - Kalp efekti motoru\n * Tek canvas, önceden çizilmiş kalp sprite'ı, düşük adet, sekme gizliyken durur.\n * Kullanım: var h = LoveHearts(); h.set({enabled:true, color:'#ffffff', density:'mid'});\n */\n(function (root) {\n  'use strict';\n\n  function LoveHearts() {\n    var canvas = null, ctx = null, raf = 0, last = 0;\n    var hearts = [], sprite = null, spriteColor = '';\n    var W = 0, H = 0, dpr = 1;\n    var cfg = { enabled: false, color: '#ffffff', density: 'mid' };\n    var mq = root.matchMedia ? root.matchMedia('(prefers-reduced-motion: reduce)') : null;\n    var COUNTS = { low: 8, mid: 14, high: 22 };\n\n    function makeSprite(color) {\n      var s = document.createElement('canvas');\n      s.width = s.height = 64;\n      var c = s.getContext('2d');\n      c.translate(32, 33);\n      c.shadowColor = color;\n      c.shadowBlur = 7;\n      c.fillStyle = color;\n      c.beginPath();\n      c.moveTo(0, -8);\n      c.bezierCurveTo(0, -18, -16, -20, -16, -8);\n      c.bezierCurveTo(-16, 4, -4, 12, 0, 20);\n      c.bezierCurveTo(4, 12, 16, 4, 16, -8);\n      c.bezierCurveTo(16, -20, 0, -18, 0, -8);\n      c.fill();\n      return s;\n    }\n\n    function targetCount() {\n      var n = COUNTS[cfg.density] || COUNTS.mid;\n      if (W < 640) n = Math.round(n * 0.65);          // mobilde daha az kalp\n      if (mq && mq.matches) n = Math.round(n * 0.5);  // hareket azaltma tercihi\n      return Math.max(3, n);\n    }\n\n    function spawn(initial) {\n      var size = 9 + Math.random() * 12;\n      return {\n        x: Math.random() * W,\n        y: initial ? Math.random() * (H + 40) : H + size + Math.random() * 60,\n        size: size,\n        vy: 16 + Math.random() * 20,                 // px / sn - yavaş yükselir\n        amp: 6 + Math.random() * 14,\n        freq: 0.4 + Math.random() * 0.6,\n        ph: Math.random() * 6.283,\n        a: 0.28 + Math.random() * 0.32,\n        t: 0\n      };\n    }\n\n    function resize() {\n      if (!canvas) return;\n      dpr = Math.min(root.devicePixelRatio || 1, 1.5);\n      W = root.innerWidth; H = root.innerHeight;\n      canvas.width = Math.round(W * dpr);\n      canvas.height = Math.round(H * dpr);\n      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n    }\n\n    function ensureCanvas() {\n      if (canvas) return;\n      canvas = document.createElement('canvas');\n      canvas.className = 'lp-hearts';\n      canvas.setAttribute('aria-hidden', 'true');\n      canvas.style.cssText = 'position:fixed;left:0;top:0;width:100%;height:100%;pointer-events:none;z-index:30';\n      ctx = canvas.getContext('2d');\n      document.body.appendChild(canvas);\n      resize();\n      root.addEventListener('resize', function () { resize(); fit(); });\n    }\n\n    function fit() {\n      var n = targetCount();\n      while (hearts.length < n) hearts.push(spawn(true));\n      if (hearts.length > n) hearts.length = n;\n    }\n\n    function frame(now) {\n      raf = 0;\n      if (!cfg.enabled || document.hidden) return;\n      var dt = Math.min(0.05, (now - last) / 1000 || 0.016);\n      last = now;\n      ctx.clearRect(0, 0, W, H);\n      var slow = mq && mq.matches ? 0.6 : 1;\n      for (var i = 0; i < hearts.length; i++) {\n        var h = hearts[i];\n        h.t += dt;\n        h.y -= h.vy * dt * slow;\n        var prog = 1 - (h.y + h.size) / (H + h.size * 2);       // 0 altta, 1 üstte\n        if (prog > 1.02) { hearts[i] = spawn(false); continue; }\n        var fade = Math.min(1, prog * 6) * Math.min(1, (1 - prog) * 3.5);\n        var x = h.x + Math.sin(h.t * h.freq + h.ph) * h.amp;\n        ctx.globalAlpha = Math.max(0, h.a * fade);\n        ctx.drawImage(sprite, x - h.size / 2, h.y - h.size / 2, h.size, h.size);\n      }\n      ctx.globalAlpha = 1;\n      raf = requestAnimationFrame(frame);\n    }\n\n    function start() { if (!raf && cfg.enabled && !document.hidden) { last = performance.now(); raf = requestAnimationFrame(frame); } }\n    function stop() { if (raf) cancelAnimationFrame(raf); raf = 0; if (ctx) ctx.clearRect(0, 0, W, H); }\n\n    document.addEventListener('visibilitychange', function () { document.hidden ? stop() : start(); });\n\n    return {\n      set: function (next) {\n        cfg = { enabled: !!next.enabled, color: next.color || '#ffffff', density: next.density || 'mid' };\n        if (!cfg.enabled) { stop(); if (canvas) canvas.style.display = 'none'; return; }\n        ensureCanvas();\n        canvas.style.display = '';\n        if (spriteColor !== cfg.color) { sprite = makeSprite(cfg.color); spriteColor = cfg.color; }\n        fit();\n        start();\n      }\n    };\n  }\n\n  root.LoveHearts = LoveHearts;\n})(window);\n"};
